/* **************************************** */
/*          INSTRUCCIONES INICIALES         */
/* **************************************** */
SET CLIENT_ENCODING TO 'UTF8';

/* **************************************** */
/*                 ESQUEMA                  */
/* **************************************** */

-- país
create table public.pais (
  id bigint primary key not null,
  nombre character varying(100) not null
);

-- usuario
create table public.usuario (
  id bigint primary key not null,
  nombre character varying(100) not null,
  apellido character varying(100) not null,
  correo character varying(254) not null,
  contrasena character varying(100) not null,
  telefono character varying(15) not null,
  nacionalidad_id bigint not null,
  foreign key (nacionalidad_id) references public.pais (id)
  match simple on update no action on delete no action
);
create unique index usuario_correo_key on usuario using btree (correo);
create index usuario_correo_5d0f2e9c_like on usuario using btree (correo);
create index usuario_nacionalidad_id_88b58c79 on usuario using btree (nacionalidad_id);

-- categoría
create table public.categoria (
  id bigint primary key not null,
  nombre character varying(100) not null
);
create unique index categoria_nombre_key on categoria using btree (nombre);
create index categoria_nombre_872f9ecc_like on categoria using btree (nombre);

-- autor
create table public.autor (
  id bigint primary key not null,
  nombre character varying(100) not null,
  apellido character varying(100) not null,
  fecha_nacimiento date not null,
  nacionalidad_id bigint not null,
  foreign key (nacionalidad_id) references public.pais (id)
  match simple on update no action on delete no action
);
create index autor_nacionalidad_id_3fa060d9 on autor using btree (nacionalidad_id);

-- libro
create table public.libro (
  id bigint primary key not null,
  isbn character varying(13) not null,
  titulo character varying(100) not null,
  edicion smallint not null,
  autor_id bigint not null,
  categoria_id bigint not null,
  foreign key (autor_id) references public.autor (id)
  match simple on update no action on delete no action,
  foreign key (categoria_id) references public.categoria (id)
  match simple on update no action on delete no action
);
create unique index libro_isbn_key on libro using btree (isbn);
create index libro_isbn_bf1430c8_like on libro using btree (isbn);
create index libro_autor_id_fbb5db20 on libro using btree (autor_id);
create index libro_categoria_id_f3d2070e on libro using btree (categoria_id);

-- inventario
create table public.inventario (
  id bigint primary key not null,
  estante character varying(1) not null,
  coordenada integer not null,
  libro_id bigint,
  foreign key (libro_id) references public.libro (id)
  match simple on update no action on delete no action
);
create index inventario_libro_id_da8f52ba on inventario using btree (libro_id);

-- prestamo
create table public.prestamo (
  id bigint primary key not null,
  fecha_inicio date not null,
  fecha_fin date not null,
  fecha_retorno date,
  inventario_id bigint not null,
  usuario_id bigint not null,
  foreign key (inventario_id) references public.inventario (id)
  match simple on update no action on delete no action,
  foreign key (usuario_id) references public.usuario (id)
  match simple on update no action on delete no action
);
create index prestamo_inventario_id_a7b4625a on prestamo using btree (inventario_id);
create index prestamo_usuario_id_019b23d1 on prestamo using btree (usuario_id);

-- rainbow
create table public.rainbow (
  id bigint primary key not null,
  contrasena character varying(100) not null,
  hash character varying(100) not null
);

/* **************************************** */
/*                  DATOS                   */
/* **************************************** */

